def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    pressured_opponents = 0
    rich_opponents = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) > 200:
                rich_opponents += 1
            if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
                pressured_opponents += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    if hp <= 2 or no_water >= 2:
        bid = max(72.0, highest_prev * 0.72)
        if tight_supply:
            bid = max(bid, 92.0)
        return float(min(budget, bid))

    if hp <= 4 or no_water >= 1:
        bid = max(48.0, avg_prev * 0.45)
        if tight_supply:
            bid = max(bid, 62.0)
        elif loose_supply:
            bid = min(bid, 55.0)
        return float(min(budget, bid))

    if highest_prev >= 120:
        bid = 24.0
    elif highest_prev >= 70:
        bid = 31.0
    else:
        bid = 36.0

    if tight_supply:
        bid += 10.0
    elif loose_supply:
        bid -= 6.0

    if rich_opponents >= 2:
        bid += 4.0
    if pressured_opponents >= 2:
        bid -= 3.0

    reserve_target = DAILY_SALARY * 3
    if budget < reserve_target:
        bid = min(bid, 28.0)

    bid = max(12.0, bid)
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(my_status['budget'], 20.0))

    prev_bids = [o.get('previous_trace', {}).get('bid', 0) for o in alive_opponents if o.get('previous_trace')]
    max_prev = max(prev_bids) if prev_bids else 0

    if my_status['hp'] <= 3:
        return float(min(my_status['budget'], max(max_prev * 1.1, 60.0)))

    if day_context['supply'] < WATER_REQ * 1.5:
        return float(min(my_status['budget'], max(max_prev * 0.9, 45.0)))

    return float(min(my_status['budget'], 35.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = {aid: opp for aid, opp in opponents_status.items() if opp['alive']}
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])
    hp = my_status['hp']
    budget = my_status['budget']
    if hp <= 2:
        target = min(budget, DAILY_SALARY * 1.0)  # urgent
    elif hp <= 5:
        target = min(budget, DAILY_SALARY * 0.75)
    else:
        target = min(budget, DAILY_SALARY * 0.55)
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        bid = min(budget, max(target, max_prev + 1.0))
    else:
        bid = target
    # ensure numeric (float) is okay, no list indexing needed
    return bid
